                    text(
                        "CREATE UNIQUE INDEX IF NOT EXISTS "
                        "ix_proof_lifecycle_events_scope_commit_seq "
                        "ON proof_lifecycle_events "
                        "(tenant_id, workload_id, commit_seq)"
                    )
                )

